mapper.select:
SELECT USER_ID, USER_NAME, ROLE_CODE, USE_YN, LAST_LOGIN_DATE, CREATED_AT, CREATED_BY, UPDATED_AT, UPDATED_BY FROM MST_USER WHERE 1=1
AND USER_ID = #{dto.userId}
ORDER BY CREATED_AT DESC OFFSET #{dto.offset} ROWS FETCH NEXT #{dto.size} ROWS ONLY

