USER_PW = #{dto.userPw}, USER_NAME = #{dto.userName}, ROLE_CODE = #{dto.roleCode}, USE_YN = #{dto.useYn}, UPDATED_AT = SYSDATE, UPDATED_BY = #{loginUserId}
WHERE USER_ID = #{userId}
